//! Generation of `docker-compose.yml` and the files it mounts.

pub mod yaml;

use std::path::{Path, PathBuf};

pub use yaml::Yaml;

use crate::config::{write_atomic, AppConfig, ConfigError};
use crate::engines::EngineId;
use crate::paths::AppPaths;

/// Compose project name used for every command.
pub const PROJECT: &str = "dbdock";

/// Profile of engines that must never start from a plain `docker compose up`
/// (InterBase needs a registered license first).
pub const MANUAL_PROFILE: &str = "interbase";

const HEADER: &str = "\
# Generated by DBDock (https://github.com/Pascold/DBDock).
# Changes made here are overwritten the next time DBDock starts a database.
# Usage without DBDock: docker compose up -d
# Passwords are in plain text on purpose: these are local test databases.

";

/// Everything the generator needs besides the configuration.
#[derive(Debug, Clone, Copy)]
pub struct ComposeContext<'a> {
    pub paths: &'a AppPaths,
    /// Host user and group that should own files created in bind mounts
    /// (Unix only; containers run as root otherwise).
    pub owner: Option<(u32, u32)>,
}

impl<'a> ComposeContext<'a> {
    /// Context for the current host.
    pub fn for_host(paths: &'a AppPaths) -> Self {
        Self {
            paths,
            owner: host_owner(paths.base()),
        }
    }
}

#[cfg(unix)]
fn host_owner(dir: &Path) -> Option<(u32, u32)> {
    use std::os::unix::fs::MetadataExt as _;
    std::fs::metadata(dir).ok().map(|m| (m.uid(), m.gid()))
}

#[cfg(not(unix))]
fn host_owner(_dir: &Path) -> Option<(u32, u32)> {
    None
}

/// Builds the compose document for all enabled engines.
pub fn generate(config: &AppConfig, ctx: &ComposeContext<'_>) -> String {
    let mut services = Yaml::map();
    let mut volumes = Yaml::map();
    for id in enabled(config) {
        let engine = id.engine();
        let settings = config.engine(id);
        for (name, service) in engine.services(settings, ctx) {
            services.insert(name, service);
        }
        for volume in engine.volumes().iter().chain(engine.kept_volumes()) {
            volumes.insert(*volume, Yaml::map());
        }
    }

    let mut doc = Yaml::map().with("name", PROJECT).with("services", services);
    if matches!(&volumes, Yaml::Map(v) if !v.is_empty()) {
        doc.insert("volumes", volumes);
    }
    format!("{HEADER}{}", doc.to_yaml_string())
}

/// Writes the compose file together with seed scripts and helper files and
/// creates the SQLite folder. Returns the path of the compose file.
pub fn write_files(config: &AppConfig, ctx: &ComposeContext<'_>) -> Result<PathBuf, ConfigError> {
    let paths = ctx.paths;
    let sqlite_dir = paths.sqlite_dir();
    std::fs::create_dir_all(&sqlite_dir).map_err(|source| ConfigError::Io {
        path: sqlite_dir,
        source,
    })?;
    // Seeds are written for every engine (also disabled ones) so a bind mount
    // never points at a missing file, which Docker would turn into a folder.
    for id in EngineId::ALL {
        let engine = id.engine();
        if let Some(sql) = engine.seed_sql() {
            write_atomic(&paths.seed_file(id), sql.as_bytes())?;
        }
        for (name, contents) in engine.helper_files() {
            write_atomic(&paths.seed_dir().join(name), contents.as_bytes())?;
        }
    }
    let compose = paths.compose_file();
    write_atomic(&compose, generate(config, ctx).as_bytes())?;
    Ok(compose)
}

/// Enabled engines in display order.
pub fn enabled(config: &AppConfig) -> impl Iterator<Item = EngineId> + '_ {
    EngineId::ALL
        .into_iter()
        .filter(|&id| config.engine(id).enabled)
}

// ---------------------------------------------------------------------------
// Helpers for engine implementations
// ---------------------------------------------------------------------------

/// Escapes `$` so Compose does not treat user values as variables.
pub fn escape(value: &str) -> String {
    value.replace('$', "$$")
}

/// `environment:` map; values are escaped with [`escape`].
pub fn environment<'v>(pairs: impl IntoIterator<Item = (&'static str, &'v str)>) -> Yaml {
    pairs.into_iter().fold(Yaml::map(), |map, (key, value)| {
        map.with(key, escape(value))
    })
}

/// Port published on the loopback interface only.
pub fn ports(host: u16, container: u16) -> Yaml {
    Yaml::strings([format!("127.0.0.1:{host}:{container}")])
}

/// Long-syntax bind mount (safe for Windows paths with drive letters).
pub fn bind(source: &Path, target: &str, read_only: bool) -> Yaml {
    Yaml::map()
        .with("type", "bind")
        .with("source", source.to_string_lossy().into_owned())
        .with("target", target)
        .with("read_only", read_only)
}

/// Long-syntax named volume.
pub fn volume(name: &str, target: &str) -> Yaml {
    Yaml::map()
        .with("type", "volume")
        .with("source", name)
        .with("target", target)
}

/// `healthcheck:` running `command` through the container shell. Use `$$VAR`
/// to read container environment variables.
pub fn healthcheck(command: &str, interval_s: u32, retries: i64, start_period_s: u32) -> Yaml {
    Yaml::map()
        .with("test", Yaml::strings(["CMD-SHELL", command]))
        .with("interval", format!("{interval_s}s"))
        .with("timeout", "10s")
        .with("retries", retries)
        .with("start_period", format!("{start_period_s}s"))
}

/// Base service definition shared by all engines.
pub fn service(image: String) -> Yaml {
    Yaml::map().with("image", image)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::EngineSettings;

    fn paths() -> AppPaths {
        AppPaths::new("/home/tester/.config/dbdock")
    }

    /// Generated output with Windows path separators normalised, so the
    /// snapshots are identical on every platform.
    fn render(config: &AppConfig, owner: Option<(u32, u32)>) -> String {
        let paths = paths();
        let ctx = ComposeContext {
            paths: &paths,
            owner,
        };
        generate(config, &ctx).replace("\\\\", "/")
    }

    fn settings(config: &mut AppConfig, id: EngineId) -> &mut EngineSettings {
        config.engine_mut(id)
    }

    #[test]
    fn default_config() {
        insta::assert_snapshot!(render(&AppConfig::default(), None));
    }

    #[test]
    fn modified_config() {
        let mut config = AppConfig::default();
        let pg = settings(&mut config, EngineId::Postgres);
        pg.version = "18".into();
        pg.port = 15432;
        pg.password = "pa$$word".into();
        pg.seed = false;
        let ms = settings(&mut config, EngineId::MsSql);
        ms.version = "2025-latest".into();
        ms.admin_password = "Str0ng#Pass".into();
        ms.seed = false;
        settings(&mut config, EngineId::MariaDb).enabled = false;
        settings(&mut config, EngineId::InterBase).enabled = true;
        insta::assert_snapshot!(render(&config, Some((1000, 1000))));
    }

    #[test]
    fn only_sqlite() {
        let mut config = AppConfig::default();
        for id in EngineId::ALL {
            settings(&mut config, id).enabled = id == EngineId::Sqlite;
        }
        insta::assert_snapshot!(render(&config, None));
    }

    #[test]
    fn nothing_enabled() {
        let mut config = AppConfig::default();
        for id in EngineId::ALL {
            settings(&mut config, id).enabled = false;
        }
        assert!(render(&config, None).ends_with("name: \"dbdock\"\nservices: {}\n"));
    }

    #[test]
    fn dollar_signs_are_escaped() {
        assert_eq!(escape("a$b$$c"), "a$$b$$$$c");
    }

    #[test]
    fn write_files_creates_everything() {
        let dir = tempfile::tempdir().unwrap();
        let paths = AppPaths::new(dir.path());
        let ctx = ComposeContext {
            paths: &paths,
            owner: None,
        };
        let compose = write_files(&AppConfig::default(), &ctx).unwrap();
        assert!(compose.is_file());
        assert!(paths.sqlite_dir().is_dir());
        for id in EngineId::ALL {
            assert_eq!(
                paths.seed_file(id).is_file(),
                id.engine().seed_sql().is_some(),
                "{id:?}"
            );
        }
        assert!(paths.seed_dir().join("mssql-init.sql").is_file());
    }
}
